<?php
require "db.php";$q=trim((string)($_GET["q"]??""));
$sql="SELECT f.id,f.name,f.phone,f.address,f.opening_balance,COALESCE(a.bill_count,0) bill_count,COALESCE(a.total_value,0) total_value,COALESCE(a.outstanding,0) bill_outstanding,(f.opening_balance+COALESCE(a.outstanding,0)) current_balance FROM farmers f LEFT JOIN (SELECT b.farmer_id,COUNT(b.id) bill_count,SUM(b.total_amount) total_value,SUM(b.total_amount-b.paid_amount-COALESCE(p.extra_paid,0)) outstanding FROM bills b LEFT JOIN (SELECT bill_id,SUM(amount) extra_paid FROM bill_payments GROUP BY bill_id) p ON p.bill_id=b.id GROUP BY b.farmer_id) a ON a.farmer_id=f.id WHERE f.name LIKE CONCAT('%',?,'%') OR f.phone LIKE CONCAT('%',?,'%') ORDER BY f.id DESC";
$stmt=$conn->prepare($sql);$stmt->bind_param("ss",$q,$q);$stmt->execute();$rows=$stmt->get_result();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JM PADDY | Farmers</title><link rel="stylesheet" href="style.css"></head><body><div class="app"><aside class="sidebar"><h2>🌾 JM PADDY</h2><p class="subtitle">Paddy Billing System</p><nav><a href="dashboard.php">🏠 Dashboard</a><a href="bill.php">🧾 Create Bill</a><a class="active" href="farmers.php">👨‍🌾 Farmers</a><a href="history.php">📋 Bill History</a><a href="reports.php">📈 Reports</a><a href="prices.php">💰 Rates & Prices</a><a href="settings.php">⚙️ Settings</a></nav></aside><main class="main"><header class="topbar"><div><h1>Farmers & Outstanding Balances</h1><p>Search farmers, review their total outstanding and add any opening balance carried over from your old records.</p></div><a class="btn" href="bill.php">＋ New Bill</a></header><?php if(isset($_GET["saved"])): ?><section class="panel">✓ Opening balance updated.</section><?php endif;?><section class="panel"><form method="get" class="grid" style="margin-bottom:18px"><div><label for="q">Search farmer name or phone</label><input id="q" name="q" value="<?= htmlspecialchars($q) ?>" placeholder="Type a name or phone"></div><div style="align-self:end"><button class="btn" type="submit">Search</button> <a class="btn" style="background:#718078" href="farmers.php">Clear</a></div></form><div style="overflow-x:auto"><table><thead><tr><th>Farmer</th><th>Phone</th><th>Bills</th><th>Bill Value</th><th>Opening Balance (Rs.)</th><th>Current Balance</th></tr></thead><tbody><?php if($rows&&$rows->num_rows):while($r=$rows->fetch_assoc()): ?><tr><td><strong><?= htmlspecialchars($r["name"]) ?></strong><br><small><?= htmlspecialchars($r["address"]?: "") ?></small></td><td><?= htmlspecialchars($r["phone"]?: "—") ?></td><td><?= (int)$r["bill_count"] ?></td><td>Rs. <?= number_format((float)$r["total_value"],2) ?></td><td><form method="post" action="update_farmer_balance.php" style="display:flex;gap:6px;min-width:220px"><input type="hidden" name="farmer_id" value="<?= (int)$r["id"] ?>"><input type="number" name="opening_balance" min="0" step="0.01" value="<?= number_format((float)$r["opening_balance"],2,".","") ?>" aria-label="Opening balance for <?= htmlspecialchars($r["name"]) ?>" required><button class="btn" type="submit" style="padding:8px 10px">Save</button></form></td><td><strong>Rs. <?= number_format(max(0,(float)$r["current_balance"]),2) ?></strong></td></tr><?php endwhile;else: ?><tr><td colspan="6" style="text-align:center;padding:25px">No matching farmer records found. Save a bill first to add a farmer.</td></tr><?php endif;?></tbody></table></div><p><b>Opening balance</b> is money already owed before JM PADDY started tracking the farmer. It is added automatically to future bill calculations. The current balance updates after bills and payments.</p></section></main></div></body></html>